  scrollbar-width: thin;
  scrollbar-color: rgba(170, 181, 186, 0.3) transparent;
}
.main_ui_components_button_link__new-scrollbar:hover {
  scrollbar-color: rgba(170, 181, 186, 0.7) transparent;
}
