  cursor: pointer;
  height: 0.75rem;
  width: 0.75rem;
}
.main_ui_components_button_link__new-scrollbar ::-webkit-scrollbar-track,
.main_ui_components_button_link__new-scrollbar ::-webkit-scrollbar-corner {
  background-color: transparent;
}
.main_ui_components_button_link__new-scrollbar ::-webkit-scrollbar-thumb {
  background-color: rgba(170, 181, 186, 0.3);
  background-clip: content-box;
  border: 0.125rem solid transparent;
  border-radius: 0.5rem;
}
